const PAGE = "\u003c!doctype html>\n\u003chtml lang=\"en\" data-theme=\"dark\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n\u003c!-- Safety: this page may only talk to Google's Gemini service, nobody else. -->\n\u003cmeta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src data:; connect-src 'self'\">\n\u003ctitle>Nova AI\u003c/title>\n\u003clink rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='9' fill='%230a0a0e'/%3E%3Cpath d='M16 4c1 7 5 11 12 12-7 1-11 5-12 12-1-7-5-11-12-12 7-1 11-5 12-12z' fill='%238b7cf6'/%3E%3C/svg%3E\">\n\u003cstyle>\n:root,[data-theme=dark]{--base:#0a0a0e;--panel:#121219;--raised:#1c1c27;--line:#2c2c3c;--ink:#ececf4;--muted:#9292a8;--accent:#8b7cf6;--accent2:#5aa2ff;--danger:#ff7878;color-scheme:dark}\n[data-theme=light]{--base:#f7f7fb;--panel:#ffffff;--raised:#eeeef7;--line:#dadae8;--ink:#181824;--muted:#64647c;--accent:#6854e8;--accent2:#2876eb;--danger:#c83232;color-scheme:light}\n*{box-sizing:border-box}\nhtml,body{height:100%;margin:0}\nbody{background:var(--base);color:var(--ink);font:15.5px/1.6 \"Segoe UI\",system-ui,-apple-system,Roboto,sans-serif;transition:background .25s,color .25s}\nbutton{font:inherit;color:inherit;background:none;border:0;cursor:pointer}\n:focus-visible{outline:2px solid var(--accent2);outline-offset:2px}\n.display{font-family:\"Segoe UI Variable Display\",\"Segoe UI\",system-ui,sans-serif;letter-spacing:-.02em}\n#app{display:flex;height:100dvh;overflow:hidden}\n#sidebar{width:18rem;flex-shrink:0;background:var(--panel);border-right:1px solid var(--line);display:flex;flex-direction:column;overflow:hidden;transition:width .3s,transform .3s}\n#sidebar.closed{width:0;border-right-color:transparent}\n.sb-inner{width:18rem;height:100%;display:flex;flex-direction:column}\n.brand{display:flex;align-items:center;justify-content:space-between;padding:16px 16px 12px}\n.brand span{font-size:20px;font-weight:650;margin-left:10px}\n.brand div{display:flex;align-items:center}\n.icon-btn{width:38px;height:38px;border-radius:12px;display:inline-flex;align-items:center;justify-content:center;color:var(--muted);transition:background .15s,color .15s}\n.icon-btn:hover{background:var(--raised);color:var(--ink)}\n.icon-btn svg{width:18px;height:18px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n#newchat{margin:0 12px 12px;display:flex;align-items:center;gap:10px;padding:10px 14px;border:1px solid var(--line);border-radius:12px;background:color-mix(in srgb,var(--raised) 60%,transparent);font-weight:550;font-size:14px;transition:border-color .15s,background .15s}\n#newchat:hover{border-color:color-mix(in srgb,var(--accent) 60%,transparent);background:var(--raised)}\n#newchat svg{width:17px;height:17px;stroke:var(--accent);fill:none;stroke-width:1.8;stroke-linecap:round}\n#list{flex:1;min-height:0;overflow-y:auto;padding:0 12px 16px}\n#list h3{margin:14px 12px 6px;font-size:12px;font-weight:550;color:var(--muted)}\n.empty{padding:22px 12px;color:var(--muted);font-size:14px;line-height:1.6}\n.row{position:relative;display:flex;align-items:center;border-radius:12px;transition:background .15s}\n.row:hover,.row.active{background:var(--raised)}\n.row.active::before{content:\"\";position:absolute;left:0;top:8px;bottom:8px;width:2px;border-radius:2px;background:var(--accent)}\n.row .t{flex:1;min-width:0;text-align:left;padding:10px 12px;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.row .ops{display:flex;padding-right:4px}\n.row .ops button{width:30px;height:30px;border-radius:8px;color:var(--muted);display:flex;align-items:center;justify-content:center}\n.row .ops button:hover{background:var(--line);color:var(--ink)}\n.row .ops svg{width:15px;height:15px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n@media(hover:hover){.row .ops{opacity:0;transition:opacity .15s}.row:hover .ops,.row:focus-within .ops{opacity:1}}\nmain{flex:1;min-width:0;display:flex;flex-direction:column;position:relative}\nheader{height:56px;flex-shrink:0;display:flex;align-items:center;gap:4px;padding:0 10px}\nheader h1{flex:1;min-width:0;margin:0 8px;font-size:15px;font-weight:550;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n#scroller{flex:1;min-height:0;overflow-y:auto}\n#welcome{max-width:760px;min-height:100%;margin:0 auto;padding:40px 16px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}\n.orb{position:relative;margin-bottom:28px;animation:rise .3s both}\n.orb::before{content:\"\";position:absolute;left:50%;top:50%;width:176px;height:176px;margin:-88px 0 0 -88px;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--accent) 60%,transparent),color-mix(in srgb,var(--accent2) 28%,transparent) 60%,transparent 75%);filter:blur(40px);opacity:.6;animation:drift 7s ease-in-out infinite}\n.orb svg{position:relative;display:block;animation:drift 7s ease-in-out infinite}\n#welcome h2{margin:0;max-width:440px;font-size:34px;line-height:1.2;font-weight:650;animation:rise .3s .06s both}\n.sugs{margin-top:36px;width:100%;max-width:680px;display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.sug{text-align:left;padding:16px;border:1px solid var(--line);border-radius:16px;background:color-mix(in srgb,var(--panel) 70%,transparent);transition:border-color .15s,background .15s;animation:rise .3s both}\n.sug:hover{border-color:color-mix(in srgb,var(--accent) 60%,transparent);background:var(--raised)}\n.sug b{display:block;font-size:14px}\n.sug span{display:block;margin-top:4px;font-size:14px;line-height:1.4;color:var(--muted)}\n.keynote{margin-top:22px;padding:12px 16px;border:1px solid color-mix(in srgb,var(--accent) 50%,transparent);border-radius:14px;background:color-mix(in srgb,var(--accent) 10%,transparent);font-size:14px}\n.keynote button{margin-left:8px;padding:6px 12px;border-radius:10px;background:linear-gradient(135deg,var(--accent),var(--accent2));color:#fff;font-weight:600;font-size:13px}\n#messages{max-width:760px;margin:0 auto;padding:24px 16px;display:flex;flex-direction:column;gap:28px}\n.msg{animation:rise .25s both}\n.msg.user{display:flex;justify-content:flex-end}\n.bubble{max-width:85%;white-space:pre-wrap;overflow-wrap:anywhere;background:var(--raised);padding:10px 16px;border-radius:18px 18px 6px 18px}\n.msg.assistant{display:flex;gap:12px}\n.avatar{margin-top:2px;width:32px;height:32px;flex-shrink:0;border:1px solid var(--line);border-radius:12px;background:var(--panel);display:flex;align-items:center;justify-content:center}\n.body{min-width:0;flex:1}\n.dots{display:flex;gap:6px;height:32px;align-items:center}\n.dots i{width:8px;height:8px;border-radius:50%;background:var(--accent);animation:pulse 1.2s ease-in-out infinite}\n.dots i:nth-child(2){animation-delay:.16s}.dots i:nth-child(3){animation-delay:.32s}\n.actions{display:flex;gap:4px;margin:8px 0 0 -10px}\n.actions button{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:10px;font-size:12px;color:var(--muted)}\n.actions button:hover{background:var(--raised);color:var(--ink)}\n.actions svg{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n.err{margin-top:8px;display:flex;gap:12px;padding:14px;border:1px solid color-mix(in srgb,var(--danger) 40%,transparent);background:color-mix(in srgb,var(--danger) 10%,transparent);border-radius:14px;font-size:14px}\n.err p{margin:0}.err button{margin-top:8px;padding:6px 12px;border:1px solid var(--line);border-radius:10px;background:var(--panel);font-size:12px;font-weight:600}\n.md{overflow-wrap:anywhere}.md>:first-child{margin-top:0}.md>:last-child{margin-bottom:0}\n.md p{margin:12px 0}.md h1,.md h2,.md h3,.md h4{margin:22px 0 8px;line-height:1.3;font-weight:650}\n.md h1{font-size:24px}.md h2{font-size:20px}.md h3{font-size:17px}.md h4{font-size:15px}\n.md ul,.md ol{margin:12px 0;padding-left:24px}.md li{margin:4px 0}.md li::marker{color:var(--accent)}\n.md a{color:var(--accent2)}.md blockquote{margin:14px 0;padding-left:16px;border-left:2px solid var(--accent);color:var(--muted)}\n.md hr{border:0;border-top:1px solid var(--line);margin:22px 0}\n.md code{font-family:Consolas,\"Cascadia Mono\",monospace;font-size:.88em;background:var(--raised);padding:2px 6px;border-radius:6px}\n.tw{overflow-x:auto;margin:14px 0}.md table{border-collapse:collapse;font-size:14px;width:100%}\n.md th,.md td{border:1px solid var(--line);padding:8px 12px;text-align:left;vertical-align:top}.md th{background:var(--raised)}\n.cb{margin:14px 0;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--base)}\n.cb-h{display:flex;justify-content:space-between;align-items:center;padding:6px 12px;background:var(--raised);border-bottom:1px solid var(--line);font-size:12px;color:var(--muted)}\n.cb-h button{padding:4px 8px;border-radius:8px;color:var(--muted);font-size:12px}.cb-h button:hover{background:var(--line);color:var(--ink)}\n.cb pre{margin:0;padding:14px 16px;overflow-x:auto}.cb pre code{background:none;padding:0;font-size:13px;line-height:1.6}\n#composer{padding:8px 16px calc(12px + env(safe-area-inset-bottom))}\n.cbox{max-width:760px;margin:0 auto}\n.in{display:flex;align-items:flex-end;gap:8px;padding:8px;border:1px solid var(--line);border-radius:18px;background:var(--panel);box-shadow:0 8px 24px rgba(0,0,0,.12);transition:border-color .15s}\n.in:focus-within{border-color:color-mix(in srgb,var(--accent) 70%,transparent)}\ntextarea{flex:1;min-height:44px;max-height:200px;resize:none;border:0;outline:0;background:none;color:var(--ink);font:inherit;padding:10px 12px;line-height:1.5}\ntextarea::placeholder{color:var(--muted)}\n#send{width:44px;height:44px;border-radius:12px;color:#fff;background:linear-gradient(135deg,var(--accent),var(--accent2));display:flex;align-items:center;justify-content:center;transition:filter .15s,transform .1s}\n#send:hover:not(:disabled){filter:brightness(1.1)}#send:active:not(:disabled){transform:scale(.95)}#send:disabled{opacity:.35;cursor:not-allowed}\n#send svg{width:18px;height:18px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n#stop{height:44px;padding:0 14px;border-radius:12px;border:1px solid var(--line);background:var(--raised);font-weight:600;font-size:14px;display:none;align-items:center;gap:8px}\n#stop i{width:12px;height:12px;border-radius:3px;background:currentColor}\n.note{margin:8px 0 0;text-align:center;font-size:12px;color:var(--muted)}\n#backdrop{display:none}\ndialog{width:min(92vw,440px);padding:24px;border:1px solid var(--line);border-radius:20px;background:var(--panel);color:var(--ink)}\ndialog::backdrop{background:rgba(0,0,0,.55)}\ndialog h2{margin:0 0 6px;font-size:20px}dialog p{margin:0 0 14px;color:var(--muted);font-size:14px}\ndialog label{display:block;margin:12px 0 4px;font-size:13px;font-weight:600}\ndialog input{width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:10px;background:var(--base);color:var(--ink);font:inherit}\ndialog .btns{display:flex;gap:8px;margin-top:18px;flex-wrap:wrap}\ndialog .btns button{padding:9px 16px;border-radius:10px;border:1px solid var(--line);background:var(--raised);font-weight:600;font-size:14px}\ndialog .btns .go{border:0;color:#fff;background:linear-gradient(135deg,var(--accent),var(--accent2))}\n#status{margin-top:12px;font-size:14px;min-height:20px}\ndialog a{color:var(--accent2)}\n@keyframes rise{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}\n@keyframes drift{0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-10px) scale(1.06)}}\n@keyframes pulse{0%,80%,100%{opacity:.25;transform:scale(.8)}40%{opacity:1;transform:scale(1)}}\n@media(max-width:767px){\n #sidebar{position:fixed;inset:0 auto 0 0;z-index:40;width:18rem}\n #sidebar.closed{width:18rem;transform:translateX(-100%)}\n #backdrop.show{display:block;position:fixed;inset:0;z-index:30;background:rgba(0,0,0,.55)}\n .sugs{grid-template-columns:1fr}#welcome h2{font-size:28px}\n .row .ops{opacity:1}\n}\n@media(prefers-reduced-motion:reduce){*{animation-duration:.01ms!important;transition-duration:.01ms!important}}\n\u003c/style>\n\u003c/head>\n\u003cbody>\n\u003csvg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\">\u003cdefs>\u003clinearGradient id=\"lg\" x1=\"4\" y1=\"4\" x2=\"28\" y2=\"28\" gradientUnits=\"userSpaceOnUse\">\u003cstop offset=\"0\" stop-color=\"#8b7cf6\"/>\u003cstop offset=\"1\" stop-color=\"#5aa2ff\"/>\u003c/linearGradient>\u003c/defs>\u003c/svg>\n\u003cdiv id=\"app\">\n \u003cdiv id=\"backdrop\">\u003c/div>\n \u003caside id=\"sidebar\" class=\"closed\">\u003cdiv class=\"sb-inner\">\n  \u003cdiv class=\"brand\">\u003cdiv>\u003cspan id=\"brandlogo\">\u003c/span>\u003cspan class=\"display\">Nova AI\u003c/span>\u003c/div>\n   \u003cbutton class=\"icon-btn\" id=\"closesb\" aria-label=\"Close sidebar\">\u003csvg viewBox=\"0 0 24 24\">\u003crect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"3\"/>\u003cpath d=\"M9 4v16\"/>\u003c/svg>\u003c/button>\u003c/div>\n  \u003cbutton id=\"newchat\">\u003csvg viewBox=\"0 0 24 24\">\u003cpath d=\"M12 5v14M5 12h14\"/>\u003c/svg>New chat\u003c/button>\n  \u003cnav id=\"list\" aria-label=\"Chat history\">\u003c/nav>\n \u003c/div>\u003c/aside>\n \u003cmain>\n  \u003cheader>\n   \u003cbutton class=\"icon-btn\" id=\"opensb\" aria-label=\"Open sidebar\">\u003csvg viewBox=\"0 0 24 24\">\u003crect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"3\"/>\u003cpath d=\"M9 4v16\"/>\u003c/svg>\u003c/button>\n   \u003ch1 class=\"display\" id=\"title\">Nova AI\u003c/h1>\n   \u003cbutton class=\"icon-btn\" id=\"settingsbtn\" aria-label=\"Settings\" title=\"API key and model\">\u003csvg viewBox=\"0 0 24 24\">\u003ccircle cx=\"12\" cy=\"12\" r=\"3\"/>\u003cpath d=\"M19.4 15a1.7 1.7 0 0 0 .3 1.8l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.7 1.7 0 0 0-1.8-.3 1.7 1.7 0 0 0-1 1.5V21a2 2 0 0 1-4 0v-.1a1.7 1.7 0 0 0-1.1-1.5 1.7 1.7 0 0 0-1.8.3l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.7 1.7 0 0 0 .3-1.8 1.7 1.7 0 0 0-1.5-1H3a2 2 0 0 1 0-4h.1a1.7 1.7 0 0 0 1.5-1.1 1.7 1.7 0 0 0-.3-1.8l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.7 1.7 0 0 0 1.8.3H9a1.7 1.7 0 0 0 1-1.5V3a2 2 0 0 1 4 0v.1a1.7 1.7 0 0 0 1 1.5 1.7 1.7 0 0 0 1.8-.3l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.7 1.7 0 0 0-.3 1.8V9a1.7 1.7 0 0 0 1.5 1H21a2 2 0 0 1 0 4h-.1a1.7 1.7 0 0 0-1.5 1Z\"/>\u003c/svg>\u003c/button>\n   \u003cbutton class=\"icon-btn\" id=\"themebtn\" aria-label=\"Switch theme\">\u003c/button>\n  \u003c/header>\n  \u003cdiv id=\"scroller\">\u003c/div>\n  \u003cdiv id=\"composer\">\u003cdiv class=\"cbox\">\n   \u003cdiv class=\"in\">\u003ctextarea id=\"input\" rows=\"1\" placeholder=\"Message Nova AI\" aria-label=\"Message Nova AI\">\u003c/textarea>\n    \u003cbutton id=\"stop\" aria-label=\"Stop generating\">\u003ci>\u003c/i>Stop\u003c/button>\n    \u003cbutton id=\"send\" aria-label=\"Send message\" disabled>\u003csvg viewBox=\"0 0 24 24\">\u003cpath d=\"M12 19V5M5.5 11.5 12 5l6.5 6.5\"/>\u003c/svg>\u003c/button>\u003c/div>\n   \u003cp class=\"note\">Enter to send, Shift + Enter for a new line. Nova AI can make mistakes, so double-check important facts.\u003c/p>\n  \u003c/div>\u003c/div>\n \u003c/main>\n\u003c/div>\n\u003cdialog id=\"settings\">\n \u003ch2 class=\"display\">Connect to Gemini\u003c/h2>\n \u003cp>Your key stays in this browser on this computer and is only ever sent to Google. Get a free key at \u003ca href=\"https://aistudio.google.com/apikey\" target=\"_blank\" rel=\"noopener noreferrer\">aistudio.google.com/apikey\u003c/a>.\u003c/p>\n \u003clabel for=\"keyin\">Gemini API key\u003c/label>\u003cinput id=\"keyin\" autofocus type=\"password\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"Paste your key here\">\n \u003clabel for=\"modelin\">Model\u003c/label>\u003cinput id=\"modelin\" type=\"text\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"gemini-2.5-flash\">\n \u003cdiv id=\"status\" role=\"status\">\u003c/div>\n \u003cdiv class=\"btns\">\u003cbutton class=\"go\" id=\"savekey\">Save\u003c/button>\u003cbutton id=\"testkey\">Test connection\u003c/button>\u003cbutton id=\"closeset\">Close\u003c/button>\u003c/div>\n\u003c/dialog>\n\n\u003cscript id=\"knowledge\" type=\"application/json\">[]\u003c/script>\n\u003cscript>\n\"use strict\";\n/* ============================================================\n   OPTIONAL: to let everyone who opens this page chat WITHOUT pasting a key,\n   paste YOUR Gemini key between the quotes on the next line, then save the file.\n   WARNING: anyone who opens this page can find that key. Use a free-tier key\n   (no billing) and only for demos. Leave it empty to make each person use their own.\n   ============================================================ */\nconst BUILT_IN_KEY=\"\";\nconst SERVER_MODE=true; // set to true automatically in the Cloudflare Worker version\n\nconst DEFAULT_MODEL=\"gemini-2.5-flash\", FALLBACK_MODEL=\"gemini-2.5-flash\";\nconst MAX_INPUT=4000, MAX_MSGS=20, MAX_CHARS=28000;\nconst SYSTEM=\"You are Nova AI, a friendly, knowledgeable assistant. Answer clearly and accurately. Use Markdown (short headings, lists, and fenced code blocks with a language tag) when it helps readability. If you are unsure about something, say so instead of guessing.\";\nconst $=id=>document.getElementById(id);\nconst LOGO=s=>`\u003csvg width=\"${s}\" height=\"${s}\" viewBox=\"0 0 32 32\" aria-hidden=\"true\">\u003cpath d=\"M16 2.5c1.2 7.7 5.8 12.3 13.5 13.5-7.7 1.2-12.3 5.8-13.5 13.5C14.8 21.8 10.2 17.2 2.5 16 10.2 14.8 14.8 10.2 16 2.5Z\" fill=\"url(#lg)\"/>\u003c/svg>`;\nconst ICON={copy:'\u003csvg viewBox=\"0 0 24 24\">\u003crect x=\"9\" y=\"9\" width=\"11\" height=\"11\" rx=\"2.5\"/>\u003cpath d=\"M5 15V6.5A2.5 2.5 0 0 1 7.5 4H15\"/>\u003c/svg>',check:'\u003csvg viewBox=\"0 0 24 24\">\u003cpath d=\"m5 12.5 4.5 4.5L19 7.5\"/>\u003c/svg>',refresh:'\u003csvg viewBox=\"0 0 24 24\">\u003cpath d=\"M20 11a8 8 0 0 0-14.5-4.2L4 8.5M4 4v4.5h4.5M4 13a8 8 0 0 0 14.5 4.2l1.5-1.7M20 20v-4.5h-4.5\"/>\u003c/svg>',pencil:'\u003csvg viewBox=\"0 0 24 24\">\u003cpath d=\"M4 20h4L19 9a2.8 2.8 0 0 0-4-4L4 16v4Z\"/>\u003c/svg>',trash:'\u003csvg viewBox=\"0 0 24 24\">\u003cpath d=\"M4 7h16M10 11v6M14 11v6M6 7l1 12a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2l1-12M9 7V4h6v3\"/>\u003c/svg>',alert:'\u003csvg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" style=\"color:var(--danger);flex-shrink:0;margin-top:2px\">\u003ccircle cx=\"12\" cy=\"12\" r=\"9\"/>\u003cpath d=\"M12 7.5v5.5M12 16.5h.01\"/>\u003c/svg>',sun:'\u003csvg viewBox=\"0 0 24 24\">\u003ccircle cx=\"12\" cy=\"12\" r=\"4\"/>\u003cpath d=\"M12 3v2M12 19v2M3 12h2M19 12h2M5.6 5.6 7 7M17 17l1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4\"/>\u003c/svg>',moon:'\u003csvg viewBox=\"0 0 24 24\">\u003cpath d=\"M20 14.5A8 8 0 0 1 9.5 4 8 8 0 1 0 20 14.5Z\"/>\u003c/svg>'};\nconst uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,8);\nconst sleep=ms=>new Promise(r=>setTimeout(r,ms));\nconst esc=s=>s.replace(/[&\u003c>\"']/g,c=>({\"&\":\"&amp;\",\"\u003c\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst store={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v)}catch{}}};\n\n/* ---------- state ---------- */\nlet chats=[],activeId=null,busy=false,controller=null,stick=true;\nlet settings={key:\"\",model:DEFAULT_MODEL};\ntry{const s=JSON.parse(store.get(\"nova-lite:settings\")||\"{}\");settings.key=(s.key||\"\").trim();settings.model=(s.model||DEFAULT_MODEL).trim()}catch{}\nif(!settings.key)settings.key=BUILT_IN_KEY.trim();\ntry{const d=JSON.parse(store.get(\"nova-lite:chats\")||\"{}\");if(Array.isArray(d.chats))chats=d.chats.filter(c=>c&&c.id&&Array.isArray(c.messages));activeId=chats.some(c=>c.id===d.activeId)?d.activeId:null}catch{}\nlet saveT=null;\nconst save=()=>{store.set(\"nova-lite:chats\",JSON.stringify({chats:chats.slice(0,60),activeId}))};\nconst saveSoon=()=>{clearTimeout(saveT);saveT=setTimeout(save,300)};\naddEventListener(\"pagehide\",save);\nconst active=()=>chats.find(c=>c.id===activeId)||null;\n\n/* ---------- markdown (small, safe: everything is escaped first) ---------- */\nfunction inline(raw){\n  const codes=[];let s=esc(raw).replace(/`([^`]+)`/g,(_,c)=>{codes.push(c);return \"\\u0000\"+(codes.length-1)+\"\\u0000\"});\n  s=s.replace(/\\*\\*([^*]+)\\*\\*/g,\"\u003cstrong>$1\u003c/strong>\").replace(/(^|[^*\\w])\\*([^*\\s][^*]*)\\*/g,\"$1\u003cem>$2\u003c/em>\");\n  s=s.replace(/\\[([^\\]]+)\\]\\((https?:\\/\\/[^\\s)]+)\\)/g,'\u003ca href=\"$2\" target=\"_blank\" rel=\"noopener noreferrer\">$1\u003c/a>');\n  return s.replace(/\\u0000(\\d+)\\u0000/g,(_,i)=>\"\u003ccode>\"+codes[i]+\"\u003c/code>\");\n}\nfunction md(src){\n  const L=src.replace(/\\r/g,\"\").split(\"\\n\"),out=[];let i=0;\n  const isBlock=l=>/^(#{1,4}\\s|```|\\s*[-*+]\\s|\\s*\\d+[.)]\\s|>)/.test(l);\n  while(i\u003cL.length){\n    let l=L[i],m;\n    if((m=l.match(/^```([\\w+#-]*)\\s*$/))){const code=[];i++;while(i\u003cL.length&&!/^```\\s*$/.test(L[i]))code.push(L[i++]);i++;\n      out.push(`\u003cdiv class=\"cb\">\u003cdiv class=\"cb-h\">\u003cspan>${esc(m[1]||\"code\")}\u003c/span>\u003cbutton data-copycode>Copy code\u003c/button>\u003c/div>\u003cpre>\u003ccode>${esc(code.join(\"\\n\"))}\u003c/code>\u003c/pre>\u003c/div>`);continue}\n    if(!l.trim()){i++;continue}\n    if((m=l.match(/^(#{1,4})\\s+(.*)$/))){out.push(`\u003ch${m[1].length}>${inline(m[2])}\u003c/h${m[1].length}>`);i++;continue}\n    if(/^(-{3,}|\\*{3,})\\s*$/.test(l)){out.push(\"\u003chr>\");i++;continue}\n    if(/^\\s*[-*+]\\s+/.test(l)){const it=[];while(i\u003cL.length&&/^\\s*[-*+]\\s+/.test(L[i]))it.push(\"\u003cli>\"+inline(L[i++].replace(/^\\s*[-*+]\\s+/,\"\"))+\"\u003c/li>\");out.push(\"\u003cul>\"+it.join(\"\")+\"\u003c/ul>\");continue}\n    if(/^\\s*\\d+[.)]\\s+/.test(l)){const it=[];while(i\u003cL.length&&/^\\s*\\d+[.)]\\s+/.test(L[i]))it.push(\"\u003cli>\"+inline(L[i++].replace(/^\\s*\\d+[.)]\\s+/,\"\"))+\"\u003c/li>\");out.push(\"\u003col>\"+it.join(\"\")+\"\u003c/ol>\");continue}\n    if(/^>/.test(l)){const q=[];while(i\u003cL.length&&/^>/.test(L[i]))q.push(L[i++].replace(/^>\\s?/,\"\"));out.push(\"\u003cblockquote>\"+inline(q.join(\" \"))+\"\u003c/blockquote>\");continue}\n    if(l.includes(\"|\")&&i+1\u003cL.length&&/^\\s*\\|?\\s*:?-{2,}:?\\s*(\\|\\s*:?-{2,}:?\\s*)*\\|?\\s*$/.test(L[i+1])){\n      const cells=r=>r.trim().replace(/^\\||\\|$/g,\"\").split(\"|\").map(c=>inline(c.trim()));\n      const head=cells(l);i+=2;const rows=[];while(i\u003cL.length&&L[i].includes(\"|\")&&L[i].trim())rows.push(cells(L[i++]));\n      out.push(`\u003cdiv class=\"tw\">\u003ctable>\u003cthead>\u003ctr>${head.map(c=>\"\u003cth>\"+c+\"\u003c/th>\").join(\"\")}\u003c/tr>\u003c/thead>\u003ctbody>${rows.map(r=>\"\u003ctr>\"+r.map(c=>\"\u003ctd>\"+c+\"\u003c/td>\").join(\"\")+\"\u003c/tr>\").join(\"\")}\u003c/tbody>\u003c/table>\u003c/div>`);continue}\n    const p=[];while(i\u003cL.length&&L[i].trim()&&!(p.length&&isBlock(L[i])))p.push(inline(L[i++]));out.push(\"\u003cp>\"+p.join(\"\u003cbr>\")+\"\u003c/p>\");\n  }\n  return out.join(\"\");\n}\n\n/* ---------- knowledge folder (datasets embedded in this file) ---------- */\nconst STOP=new Set(\"the and what how who are you for with that this can about from have please tell give explain does did was were your then than into when where which why not but all any some more most just also like make need want use using show write\".split(\" \"));\nconst wordsOf=s=>s.toLowerCase().match(/[a-z0-9]{3,}/g)||[];\nlet CHUNKS=[];\ntry{\n  const files=JSON.parse($(\"knowledge\").textContent.replace(/^\\/\\*.*?\\*\\//,\"\")||\"[]\");\n  for(const f of files){\n    let parts=[];\n    if(/\\.csv$/i.test(f.name)){const ls=f.text.split(/\\r?\\n/).filter(Boolean);for(let i=1;i\u003cls.length;i+=15)parts.push([ls[0],...ls.slice(i,i+15)].join(\"\\n\"))}\n    else{let cur=\"\";for(const p of f.text.split(/\\n\\s*\\n/)){if(cur&&cur.length+p.length>900){parts.push(cur);cur=\"\"}cur+=(cur?\"\\n\\n\":\"\")+p}if(cur)parts.push(cur)}\n    for(const t of parts)CHUNKS.push({src:f.name,text:t,w:new Set(wordsOf(t))});\n  }\n}catch{}\nfunction references(q){\n  const ws=[...new Set(wordsOf(q).filter(w=>!STOP.has(w)))];if(!ws.length)return \"\";\n  const top=CHUNKS.map(c=>({c,s:ws.reduce((n,w)=>n+(c.w.has(w)?1:0),0)})).filter(x=>x.s>0).sort((a,b)=>b.s-a.s).slice(0,3);\n  let out=\"\";for(const{c}of top){const piece=`[${c.src}]\\n${c.text}\\n\\n`;if(out.length+piece.length>3500)break;out+=piece}return out.trim();\n}\n\n/* ---------- talking to Gemini ---------- */\nfunction friendly(status,body){\n  let msg=\"\";try{msg=JSON.parse(body)?.error?.message||\"\"}catch{}\n  if(status===400&&/api key|API_KEY_INVALID/i.test(body+msg))return \"Google rejected your API key. Open Settings (gear icon), paste a fresh key from aistudio.google.com/apikey, and save.\";\n  if(status===400)return \"Google rejected the request (error 400). Check the model name in Settings, or try gemini-2.5-flash.\";\n  if(status===401||status===403)return \"Google says this key can't be used. Open Settings and paste a fresh key from aistudio.google.com/apikey.\";\n  if(status===404)return \"That model name wasn't found. Open Settings and use gemini-2.5-flash.\";\n  if(status===429)return \"The free Gemini quota is used up for the moment. Please wait a minute and try again.\";\n  if(status>=500)return `Google's AI is busy or having trouble (error ${status}). Wait a minute and try again.`;\n  return `Something went wrong (error ${status}). Please try again.`;\n}\nfunction buildHistory(msgs){\n  let u=msgs.filter(m=>!m.error&&m.content.trim()).map(m=>({role:m.role,content:m.content.slice(0,16000)})).slice(-MAX_MSGS);\n  let total=u.reduce((n,m)=>n+m.content.length,0);\n  while(u.length>1&&total>MAX_CHARS){total-=u[0].content.length;u.shift()}\n  while(u.length>1&&u[0].role!==\"user\")u.shift();\n  return u;\n}\nasync function callGemini(model,history,sys,signal){\n  const url=`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:streamGenerateContent?alt=sse&key=${encodeURIComponent(settings.key)}`;\n  return fetch(url,{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},signal,\n    body:JSON.stringify({systemInstruction:{parts:[{text:sys}]},contents:history.map(m=>({role:m.role===\"assistant\"?\"model\":\"user\",parts:[{text:m.content}]}))})});\n}\nasync function streamReply(history,onText,signal){\n  if(SERVER_MODE){\n    const r=await fetch(\"/api/chat\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},signal,body:JSON.stringify({messages:history})});\n    if(!r.ok){let m=\"\";try{m=(await r.json()).error.message}catch{}throw new Error(m||`Something went wrong (error ${r.status}). Please try again.`)}\n    const rd=r.body.getReader(),dc=new TextDecoder();let t=\"\";\n    for(;;){const{done,value}=await rd.read();if(done)break;t+=dc.decode(value,{stream:true});onText(t)}\n    t+=dc.decode();if(!t.trim())throw new Error(\"Nova AI sent back an empty reply. Try rephrasing your question.\");return t;\n  }\n  const refs=references(history.filter(m=>m.role===\"user\").slice(-2).map(m=>m.content).join(\" \"));\n  const sys=refs?`${SYSTEM}\\n\\nReference notes from the datasets built into this app are below. Use them when they help answer the question. If they are not relevant, answer normally and do not mention them.\\n\\n${refs}`:SYSTEM;\n  let model=settings.model||DEFAULT_MODEL,res=await callGemini(model,history,sys,signal);\n  if(res.status>=500){await sleep(800);res=await callGemini(model,history,sys,signal)}\n  if(!res.ok&&model!==FALLBACK_MODEL&&(res.status===400||res.status===404||res.status>=500)&&!/api key|API_KEY_INVALID/i.test(await res.clone().text()))res=await callGemini(FALLBACK_MODEL,history,sys,signal);\n  if(!res.ok)throw new Error(friendly(res.status,await res.text()));\n  const reader=res.body.getReader(),dec=new TextDecoder();let buf=\"\",text=\"\";\n  for(;;){\n    const{done,value}=await reader.read();if(done)break;\n    buf+=dec.decode(value,{stream:true});const lines=buf.split(\"\\n\");buf=lines.pop()||\"\";\n    for(const raw of lines){const ln=raw.trim();if(!ln.startsWith(\"data:\"))continue;\n      try{const j=JSON.parse(ln.slice(5));const parts=j?.candidates?.[0]?.content?.parts||[];\n        const t=parts.filter(p=>typeof p.text===\"string\"&&!p.thought).map(p=>p.text).join(\"\");if(t){text+=t;onText(text)}}catch{}}\n  }\n  if(!text.trim())throw new Error(\"Nova AI sent back an empty reply (it may have been blocked). Try rephrasing your question.\");\n  return text;\n}\n\n/* ---------- chat actions ---------- */\nasync function generate(chat,history){\n  const a={id:uid(),role:\"assistant\",content:\"\"};chat.messages.push(a);chat.updatedAt=Date.now();\n  busy=true;controller=new AbortController();const mine=controller;renderAll();\n  let raf=0;const onText=t=>{a.content=t;if(!raf)raf=requestAnimationFrame(()=>{raf=0;updateLast()})};\n  try{a.content=await streamReply(buildHistory(history),onText,mine.signal)}\n  catch(e){\n    if(mine.signal.aborted){if(!a.content.trim())chat.messages=chat.messages.filter(m=>m!==a)}\n    else a.error=e instanceof TypeError?\"Couldn't reach Google. Check your internet connection and try again.\":(e.message||\"Something went wrong. Please try again.\");\n  }\n  if(controller===mine)controller=null;busy=false;save();renderAll();\n}\nfunction send(raw){\n  const text=raw.trim().slice(0,MAX_INPUT);if(!text||busy)return;\n  if(!SERVER_MODE&&!settings.key){openSettings(\"Paste your free Gemini key to start chatting.\");return}\n  let chat=active();const um={id:uid(),role:\"user\",content:text};\n  if(chat){if(!chat.messages.length)chat.title=mkTitle(text);chat.messages.push(um);chat.updatedAt=Date.now()}\n  else{chat={id:uid(),title:mkTitle(text),createdAt:Date.now(),updatedAt:Date.now(),messages:[um]};chats.unshift(chat);activeId=chat.id}\n  stick=true;generate(chat,[...chat.messages]);\n}\nfunction regenerate(){\n  const chat=active();if(!chat||busy)return;\n  if(chat.messages.length&&chat.messages[chat.messages.length-1].role===\"assistant\")chat.messages.pop();\n  if(!chat.messages.length||chat.messages[chat.messages.length-1].role!==\"user\")return renderAll();\n  stick=true;generate(chat,[...chat.messages]);\n}\nconst mkTitle=t=>{t=t.replace(/\\s+/g,\" \").trim();return t.length>40?t.slice(0,40).trimEnd()+\"…\":t||\"New chat\"};\nconst stopGen=()=>controller&&controller.abort();\nfunction newChat(){stopGen();activeId=null;save();renderAll();closeSbMobile();$(\"input\").focus()}\nfunction selectChat(id){if(id!==activeId)stopGen();activeId=id;stick=true;save();renderAll();closeSbMobile()}\n\n/* ---------- drawing the screen ---------- */\nconst SUGS=[[\"Explain the internet\",\"Explain how the internet works, as if I'm new to technology.\"],[\"Write some code\",\"Write a Python function that removes duplicates from a list, and explain how it works.\"],[\"Plan my week\",\"Help me build a balanced weekly study routine with time for breaks.\"],[\"Spark an idea\",\"Give me five ideas for a small weekend project I can finish in two days.\"]];\nfunction groupLabel(ts){const d=86400000,t0=new Date().setHours(0,0,0,0);return ts>=t0?\"Today\":ts>=t0-d?\"Yesterday\":ts>=t0-7*d?\"Previous 7 days\":\"Older\"}\nfunction renderList(){\n  const el=$(\"list\");\n  if(!chats.length){el.innerHTML='\u003cp class=\"empty\">Your conversations will appear here once you send a message.\u003c/p>';return}\n  const sorted=[...chats].sort((a,b)=>b.updatedAt-a.updatedAt);let html=\"\",last=\"\";\n  for(const c of sorted){const g=groupLabel(c.updatedAt);if(g!==last){html+=`\u003ch3>${g}\u003c/h3>`;last=g}\n    html+=`\u003cdiv class=\"row${c.id===activeId?\" active\":\"\"}\" data-id=\"${c.id}\">\u003cbutton class=\"t\" data-act=\"open\" title=\"${esc(c.title)}\">${esc(c.title)}\u003c/button>\u003cdiv class=\"ops\">\u003cbutton data-act=\"rename\" aria-label=\"Rename chat\">${ICON.pencil}\u003c/button>\u003cbutton data-act=\"delete\" aria-label=\"Delete chat\">${ICON.trash}\u003c/button>\u003c/div>\u003c/div>`}\n  el.innerHTML=html;\n}\nfunction msgHtml(m,isLast){\n  if(m.role===\"user\")return `\u003cdiv class=\"msg user\">\u003cdiv class=\"bubble\">${esc(m.content)}\u003c/div>\u003c/div>`;\n  const waiting=busy&&isLast&&!m.content&&!m.error;\n  let h=`\u003cdiv class=\"msg assistant\" data-id=\"${m.id}\">\u003cdiv class=\"avatar\">${LOGO(18)}\u003c/div>\u003cdiv class=\"body\">`;\n  if(waiting)h+='\u003cdiv class=\"dots\" role=\"status\" aria-label=\"Nova AI is thinking\">\u003ci>\u003c/i>\u003ci>\u003c/i>\u003ci>\u003c/i>\u003c/div>';\n  h+=`\u003cdiv class=\"md\">${m.content?md(m.content):\"\"}\u003c/div>`;\n  if(m.error)h+=`\u003cdiv class=\"err\" role=\"alert\">${ICON.alert}\u003cdiv>\u003cp>${esc(m.error)}\u003c/p>${isLast&&!busy?`\u003cbutton data-act=\"regen\">Try again\u003c/button>`:\"\"}\u003c/div>\u003c/div>`;\n  if(!(busy&&isLast)&&!m.error&&m.content)h+=`\u003cdiv class=\"actions\">\u003cbutton data-act=\"copy\">${ICON.copy}Copy\u003c/button>${isLast?`\u003cbutton data-act=\"regen\">${ICON.refresh}Regenerate\u003c/button>`:\"\"}\u003c/div>`;\n  return h+\"\u003c/div>\u003c/div>\";\n}\nfunction renderAll(){\n  renderList();const c=active();$(\"title\").textContent=c?c.title:\"Nova AI\";\n  const sc=$(\"scroller\");\n  if(!c||!c.messages.length){\n    sc.innerHTML=`\u003cdiv id=\"welcome\">\u003cdiv class=\"orb\">${LOGO(68)}\u003c/div>\u003ch2 class=\"display\">Hello! I'm Nova AI. How can I help you today?\u003c/h2>\n      ${(settings.key||SERVER_MODE)?\"\":'\u003cdiv class=\"keynote\">Add your free Gemini key to start. \u003cbutton data-act=\"setkey\">Add key\u003c/button>\u003c/div>'}\n      \u003cdiv class=\"sugs\">${SUGS.map((s,i)=>`\u003cbutton class=\"sug\" data-prompt=\"${esc(s[1])}\" style=\"animation-delay:${140+i*50}ms\">\u003cb>${s[0]}\u003c/b>\u003cspan>${esc(s[1])}\u003c/span>\u003c/button>`).join(\"\")}\u003c/div>\u003c/div>`;\n  }else{\n    sc.innerHTML='\u003cdiv id=\"messages\">'+c.messages.map((m,i)=>msgHtml(m,i===c.messages.length-1)).join(\"\")+\"\u003c/div>\";\n  }\n  $(\"send\").style.display=busy?\"none\":\"flex\";$(\"stop\").style.display=busy?\"flex\":\"none\";\n  $(\"send\").disabled=!$(\"input\").value.trim();\n  if(stick)sc.scrollTop=sc.scrollHeight;saveSoon();\n}\nfunction updateLast(){\n  const els=document.querySelectorAll(\".msg.assistant\");const el=els[els.length-1];const c=active();if(!el||!c)return;\n  const m=c.messages[c.messages.length-1];const md_=el.querySelector(\".md\");if(md_&&m)md_.innerHTML=md(m.content);\n  const d=el.querySelector(\".dots\");if(d&&m.content)d.remove();\n  if(stick){const sc=$(\"scroller\");sc.scrollTop=sc.scrollHeight}\n}\n\n/* ---------- wiring ---------- */\nconst sb=$(\"sidebar\"),isMobile=()=>matchMedia(\"(max-width:767px)\").matches;\nfunction setSb(open){sb.classList.toggle(\"closed\",!open);$(\"backdrop\").classList.toggle(\"show\",open&&isMobile());$(\"opensb\").style.display=open&&!isMobile()?\"none\":\"\"}\nconst closeSbMobile=()=>{if(isMobile())setSb(false)};\n$(\"opensb\").onclick=()=>setSb(true);$(\"closesb\").onclick=()=>setSb(false);$(\"backdrop\").onclick=()=>setSb(false);\n$(\"newchat\").onclick=newChat;\n$(\"list\").onclick=e=>{\n  const b=e.target.closest(\"[data-act]\");if(!b)return;const row=b.closest(\".row\");const id=row&&row.dataset.id;const c=chats.find(x=>x.id===id);if(!c)return;\n  if(b.dataset.act===\"open\")selectChat(id);\n  if(b.dataset.act===\"rename\"){const t=prompt(\"Rename chat\",c.title);if(t&&t.trim()){c.title=t.replace(/\\s+/g,\" \").trim().slice(0,60);save();renderAll()}}\n  if(b.dataset.act===\"delete\"&&confirm(\"Delete this chat?\")){if(id===activeId){stopGen();activeId=null}chats=chats.filter(x=>x.id!==id);save();renderAll()}\n};\n$(\"scroller\").onclick=async e=>{\n  const sug=e.target.closest(\"[data-prompt]\");if(sug)return send(sug.dataset.prompt);\n  const b=e.target.closest(\"[data-act],[data-copycode]\");if(!b)return;\n  if(b.dataset.act===\"setkey\")return openSettings();\n  if(b.dataset.act===\"regen\")return regenerate();\n  const flash=(btn,ok,label)=>{if(!ok)return;const o=btn.innerHTML;btn.innerHTML=ICON.check+label;setTimeout(()=>btn.innerHTML=o,1600)};\n  if(b.dataset.act===\"copy\"){const c=active();const el=b.closest(\".msg\");const m=c&&c.messages.find(x=>x.id===el.dataset.id);if(m)flash(b,await copy(m.content),\"Copied\")}\n  if(b.hasAttribute(\"data-copycode\")){const code=b.closest(\".cb\").querySelector(\"code\").textContent;const o=b.textContent;if(await copy(code)){b.textContent=\"Copied\";setTimeout(()=>b.textContent=o,1600)}}\n};\nasync function copy(t){try{await navigator.clipboard.writeText(t);return true}catch{try{const ta=document.createElement(\"textarea\");ta.value=t;ta.style.cssText=\"position:fixed;opacity:0\";document.body.appendChild(ta);ta.select();const ok=document.execCommand(\"copy\");ta.remove();return ok}catch{return false}}}\n$(\"scroller\").onscroll=()=>{const s=$(\"scroller\");stick=s.scrollHeight-s.scrollTop-s.clientHeight\u003c120};\nconst input=$(\"input\");\ninput.oninput=()=>{input.value=input.value.slice(0,MAX_INPUT);input.style.height=\"auto\";input.style.height=Math.min(input.scrollHeight,200)+\"px\";$(\"send\").disabled=!input.value.trim()||busy};\ninput.onkeydown=e=>{if(e.key===\"Enter\"&&!e.shiftKey&&!e.isComposing){e.preventDefault();doSend()}};\nfunction doSend(){const v=input.value;if(!v.trim()||busy)return;if(!SERVER_MODE&&!settings.key){openSettings(\"Paste your free Gemini key to start chatting.\");return}input.value=\"\";input.style.height=\"auto\";send(v)}\n$(\"send\").onclick=doSend;$(\"stop\").onclick=stopGen;\n\nfunction setTheme(t){document.documentElement.dataset.theme=t;store.set(\"nova-lite:theme\",t);$(\"themebtn\").innerHTML=t===\"dark\"?ICON.sun:ICON.moon;$(\"themebtn\").setAttribute(\"aria-label\",t===\"dark\"?\"Switch to light mode\":\"Switch to dark mode\")}\n$(\"themebtn\").onclick=()=>setTheme(document.documentElement.dataset.theme===\"dark\"?\"light\":\"dark\");\nsetTheme(store.get(\"nova-lite:theme\")===\"light\"?\"light\":\"dark\");\n\nconst dlg=$(\"settings\"),status=$(\"status\");\nfunction openSettings(msg){$(\"keyin\").value=BUILT_IN_KEY.trim()&&settings.key===BUILT_IN_KEY.trim()?\"\":settings.key;$(\"keyin\").placeholder=BUILT_IN_KEY.trim()?\"Optional: paste your own key\":\"Paste your key here\";if(BUILT_IN_KEY.trim()&&!msg)msg=\"A key is already built into this page, so you can chat right away. You can paste your own key instead.\";$(\"modelin\").value=settings.model;status.style.color=\"var(--muted)\";status.textContent=msg||\"\";dlg.showModal()}\nfunction readForm(){settings.key=$(\"keyin\").value.trim().replace(/^[\"']|[\"']$/g,\"\")||BUILT_IN_KEY.trim();settings.model=$(\"modelin\").value.trim()||DEFAULT_MODEL;store.set(\"nova-lite:settings\",JSON.stringify(settings))}\n$(\"settingsbtn\").onclick=()=>openSettings();$(\"closeset\").onclick=()=>dlg.close();\n$(\"savekey\").onclick=()=>{readForm();status.style.color=\"var(--accent2)\";status.textContent=settings.key?\"Saved.\":\"Key cleared.\";renderAll();if(settings.key)setTimeout(()=>dlg.close(),500)};\n$(\"testkey\").onclick=async()=>{\n  readForm();if(!settings.key){status.style.color=\"var(--danger)\";status.textContent=\"Paste a key first.\";return}\n  status.style.color=\"var(--muted)\";status.textContent=\"Testing with Google...\";\n  try{\n    const url=`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(settings.model)}:generateContent?key=${encodeURIComponent(settings.key)}`;\n    const r=await fetch(url,{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},signal:AbortSignal.timeout(20000),body:JSON.stringify({contents:[{role:\"user\",parts:[{text:\"Reply with the word OK.\"}]}]})});\n    if(r.ok){status.style.color=\"#4fb88b\";status.textContent=\"Connected. The key and model work.\";renderAll()}\n    else{status.style.color=\"var(--danger)\";status.textContent=friendly(r.status,await r.text())}\n  }catch{status.style.color=\"var(--danger)\";status.textContent=\"Couldn't reach Google. Check your internet connection.\"}\n};\n\nsetSb(!isMobile());addEventListener(\"resize\",()=>{if(!isMobile())$(\"backdrop\").classList.remove(\"show\")});\n$(\"brandlogo\").innerHTML=LOGO(26);\nif(SERVER_MODE)$(\"settingsbtn\").style.display=\"none\";\nrenderAll();\nif(!SERVER_MODE&&!settings.key)setTimeout(()=>{if(!dlg.open)openSettings(\"Paste your free Gemini key to start.\")},400);\n\u003c/script>\n\u003c/body>\n\u003c/html>\n";
const DATA = [{"name":"about-nova-ai.md","text":"# About Nova AI (project notes)\n\nNova AI is a ChatGPT-style chatbot website. The interface is built with React, TypeScript and Tailwind CSS inside a Next.js project.\n\n## Architecture\nThe browser never talks to the AI directly. It sends messages to the site's own server route (/api/chat). The server checks the request, adds the secret API key from an environment variable, forwards the conversation to the AI service, and streams the answer back word by word.\n\n## Security\nThe API key is stored only on the server in the .env.local file or in the hosting provider's environment variables. The server validates input, limits message size and length, and limits how many messages one visitor can send per minute. It never logs keys or message text.\n\n## AI provider\nBy default Nova AI uses Google Gemini 2.5 Flash through Google's OpenAI-compatible endpoint. The provider and model can be changed with three settings: AI_BASE_URL, AI_MODEL and AI_API_KEY.\n\n## Knowledge folder\nFiles in the data folder are searched for each question. The most relevant pieces are given to the AI as reference notes, a simple form of retrieval-augmented generation.\n\n## Features\nStreaming answers, conversation memory, stop and regenerate buttons, copy buttons, chat history saved in the browser, rename and delete chats, light and dark themes, and a responsive layout for phones, tablets and desktops.\n\n## Limitations\nChat history is stored per browser, free AI quotas are limited, and the AI can make mistakes.\n"},{"name":"countries-and-capitals.csv","text":"country,capital,continent\nFrance,Paris,Europe\nGermany,Berlin,Europe\nItaly,Rome,Europe\nSpain,Madrid,Europe\nUnited Kingdom,London,Europe\nNetherlands,Amsterdam,Europe\nSweden,Stockholm,Europe\nNorway,Oslo,Europe\nGreece,Athens,Europe\nPoland,Warsaw,Europe\nRussia,Moscow,Europe/Asia\nTurkey,Ankara,Asia/Europe\nPakistan,Islamabad,Asia\nIndia,New Delhi,Asia\nChina,Beijing,Asia\nJapan,Tokyo,Asia\nSouth Korea,Seoul,Asia\nBangladesh,Dhaka,Asia\nIndonesia,Jakarta,Asia\nMalaysia,Kuala Lumpur,Asia\nThailand,Bangkok,Asia\nVietnam,Hanoi,Asia\nPhilippines,Manila,Asia\nSaudi Arabia,Riyadh,Asia\nIran,Tehran,Asia\nUnited Arab Emirates,Abu Dhabi,Asia\nEgypt,Cairo,Africa\nNigeria,Abuja,Africa\nKenya,Nairobi,Africa\nEthiopia,Addis Ababa,Africa\nSouth Africa,Pretoria (executive capital; Cape Town and Bloemfontein are also capitals),Africa\nUnited States,Washington D.C.,North America\nCanada,Ottawa,North America\nMexico,Mexico City,North America\nBrazil,Brasilia,South America\nArgentina,Buenos Aires,South America\nChile,Santiago,South America\nColombia,Bogota,South America\nPeru,Lima,South America\nAustralia,Canberra,Oceania\nNew Zealand,Wellington,Oceania\n"},{"name":"programming-languages.csv","text":"language,year_created,creator,typical_use\nPython,1991,Guido van Rossum,\"data science, scripting, web backends, teaching\"\nJavaScript,1995,Brendan Eich,\"websites and web apps, also servers via Node.js\"\nJava,1995,James Gosling (Sun Microsystems),\"enterprise software, Android apps, large systems\"\nPHP,1995,Rasmus Lerdorf,\"server-side websites such as WordPress\"\nRuby,1995,Yukihiro Matsumoto,\"web development with Ruby on Rails, scripting\"\nC,1972,Dennis Ritchie,\"operating systems, embedded systems, performance-critical code\"\nC++,1985,Bjarne Stroustrup,\"games, browsers, high-performance software\"\nC#,2000,Microsoft (Anders Hejlsberg),\"Windows apps, games with Unity, web backends\"\nSQL,1974,Donald Chamberlin and Raymond Boyce,\"querying and managing databases\"\nR,1993,Ross Ihaka and Robert Gentleman,\"statistics and data analysis\"\nGo,2009,Google (Robert Griesemer, Rob Pike, Ken Thompson),\"cloud services, networking tools\"\nRust,2010,Graydon Hoare (Mozilla),\"safe systems programming, performance and memory safety\"\nKotlin,2011,JetBrains,\"Android apps, backend development\"\nTypeScript,2012,Microsoft (Anders Hejlsberg),\"JavaScript with types for larger web projects\"\nSwift,2014,Apple (Chris Lattner),\"iPhone, iPad and Mac apps\"\n"},{"name":"python-basics.md","text":"# Python basics cheat sheet\n\n## Variables and types\nPython figures out types automatically: `age = 20` (int), `price = 9.99` (float), `name = \"Sara\"` (str), `ok = True` (bool).\n\n## Lists\nA list holds ordered items: `fruits = [\"apple\", \"banana\"]`. Add with `fruits.append(\"mango\")`. Loop with `for f in fruits: print(f)`.\n\n## Dictionaries\nA dictionary stores key-value pairs: `student = {\"name\": \"Ali\", \"grade\": 85}`. Read with `student[\"name\"]`.\n\n## Functions\nDefine with `def`: `def add(a, b): return a + b`. Call with `add(2, 3)`.\n\n## Removing duplicates from a list\n`unique = list(set(items))` removes duplicates but loses the order. To keep the order use `list(dict.fromkeys(items))`.\n\n## Reading a file\n`with open(\"notes.txt\") as f: text = f.read()` opens the file and closes it automatically.\n\n## Common errors\n- IndentationError: lines inside a block must be indented by the same amount.\n- NameError: you used a variable before creating it, or misspelled it.\n- TypeError: you mixed incompatible types, such as adding a number to a string.\n"},{"name":"university-study-skills.md","text":"# Study skills for university students\n\n## Planning a week\nBlock fixed commitments first (classes, work), then schedule two or three focused study sessions per day of 45 to 60 minutes, each followed by a 10 minute break. Leave one half-day free each week for catching up.\n\n## Active recall\nInstead of rereading notes, close them and write down everything you remember, then check what you missed. Practice questions and flashcards use the same idea and work better than highlighting.\n\n## Spaced repetition\nReview new material after one day, three days, one week and two weeks. Short repeated reviews beat one long cramming session.\n\n## Exam preparation\nStart at least two weeks early, make a topic checklist from the syllabus, solve past papers under a time limit, and sleep properly the night before.\n\n## Writing a report\nMake an outline first: introduction, main sections, conclusion. Write a rough draft without editing, then revise structure, then fix grammar and references last.\n\n## Presenting a project\nOpen with the problem, show a short demo, explain how it works at a high level, and finish with limitations and next steps. Practice out loud at least twice and keep slides to a few words each.\n"}];

const DEFAULT_MODEL = "gemini-2.5-flash";
const FALLBACK_MODEL = "gemini-2.5-flash";
const GEMINI = "https://generativelanguage.googleapis.com/v1beta/models/";
const SYSTEM =
  "You are Nova AI, a friendly, knowledgeable assistant. Answer clearly and accurately. Use Markdown (short headings, lists, and fenced code blocks with a language tag) when it helps readability. If you are unsure about something, say so instead of guessing.";

/* ---------- small knowledge base from the built-in datasets ---------- */
const STOP = new Set("the and what how who are you for with that this can about from have please tell give explain does did was were your then than into when where which why not but all any some more most just also like make need want use using show write".split(" "));
const wordsOf = (s) => s.toLowerCase().match(/[a-z0-9]{3,}/g) || [];
const CHUNKS = [];
for (const f of DATA) {
  const parts = [];
  if (/\.csv$/i.test(f.name)) {
    const ls = f.text.split(/\r?\n/).filter(Boolean);
    for (let i = 1; i < ls.length; i += 15) parts.push([ls[0], ...ls.slice(i, i + 15)].join("\n"));
  } else {
    let cur = "";
    for (const p of f.text.split(/\n\s*\n/)) {
      if (cur && cur.length + p.length > 900) { parts.push(cur); cur = ""; }
      cur += (cur ? "\n\n" : "") + p;
    }
    if (cur) parts.push(cur);
  }
  for (const t of parts) CHUNKS.push({ src: f.name, text: t, w: new Set(wordsOf(t)) });
}
function references(q) {
  const ws = [...new Set(wordsOf(q).filter((w) => !STOP.has(w)))];
  if (!ws.length) return "";
  const top = CHUNKS.map((c) => ({ c, s: ws.reduce((n, w) => n + (c.w.has(w) ? 1 : 0), 0) })).filter((x) => x.s > 0).sort((a, b) => b.s - a.s).slice(0, 3);
  let out = "";
  for (const { c } of top) {
    const piece = `[${c.src}]\n${c.text}\n\n`;
    if (out.length + piece.length > 3500) break;
    out += piece;
  }
  return out.trim();
}

/* ---------- helpers ---------- */
const json = (status, message, code, extra = {}) =>
  new Response(JSON.stringify({ error: { code, message } }), { status, headers: { "Content-Type": "application/json", "Cache-Control": "no-store", ...extra } });
const clean = (v) => (v || "").trim().replace(/^["']|["']$/g, "").trim();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Per-visitor limit. In Cloudflare each server instance keeps its own counter, so this is a safety net.
const hits = new Map();
function rateLimit(ip, limit, windowMs = 60000) {
  const now = Date.now();
  const recent = (hits.get(ip) || []).filter((t) => now - t < windowMs);
  if (recent.length >= limit) { hits.set(ip, recent); return Math.max(1, Math.ceil((windowMs - (now - recent[0])) / 1000)); }
  recent.push(now); hits.set(ip, recent);
  if (hits.size > 3000) for (const [k, v] of hits) if (v.every((t) => now - t >= windowMs)) hits.delete(k);
  return 0;
}

function validate(body) {
  const msgs = body && body.messages;
  if (!Array.isArray(msgs) || !msgs.length || msgs.length > 60) return null;
  const turns = [];
  let total = 0;
  for (const m of msgs) {
    if (!m || (m.role !== "user" && m.role !== "assistant") || typeof m.content !== "string" || !m.content.trim()) return null;
    if (m.content.length > 16000) return null;
    total += m.content.length;
    turns.push({ role: m.role, content: m.content });
  }
  if (total > 30000 || turns[turns.length - 1].role !== "user") return null;
  return turns.slice(-20);
}

function callGemini(env, model, turns, refs, signal) {
  const sys = refs
    ? `${SYSTEM}\n\nReference notes from the datasets built into this app are below. Use them when they help answer the question. If they are not relevant, answer normally and do not mention them.\n\n${refs}`
    : SYSTEM;
  return fetch(`${GEMINI}${encodeURIComponent(model)}:streamGenerateContent?alt=sse`, {
    method: "POST",
    headers: { "Content-Type": "application/json", "x-goog-api-key": clean(env.AI_API_KEY) },
    signal,
    body: JSON.stringify({
      systemInstruction: { parts: [{ text: sys }] },
      contents: turns.map((m) => ({ role: m.role === "assistant" ? "model" : "user", parts: [{ text: m.content }] })),
    }),
  });
}

// Turns Google's event stream into plain text for the page.
function toText(body) {
  const dec = new TextDecoder(), enc = new TextEncoder();
  let buf = "";
  return body.pipeThrough(new TransformStream({
    transform(chunk, ctl) {
      buf += dec.decode(chunk, { stream: true });
      const lines = buf.split("\n");
      buf = lines.pop() || "";
      for (const raw of lines) {
        const ln = raw.trim();
        if (!ln.startsWith("data:")) continue;
        try {
          const parts = JSON.parse(ln.slice(5))?.candidates?.[0]?.content?.parts || [];
          const t = parts.filter((p) => typeof p.text === "string" && !p.thought).map((p) => p.text).join("");
          if (t) ctl.enqueue(enc.encode(t));
        } catch (e) { /* ignore partial lines */ }
      }
    },
  }));
}

function explain(status, text) {
  if (status === 400 && /api key|API_KEY_INVALID/i.test(text)) return [503, "bad_key", "The AI service rejected the site's API key. The site owner needs to replace the AI_API_KEY secret in Cloudflare."];
  if (status === 400) return [502, "rejected", "The AI service rejected the request (error 400). The site owner should check the AI_MODEL setting."];
  if (status === 401 || status === 403) return [503, "bad_key", "The AI service says the site's API key can't be used. The site owner needs to replace the AI_API_KEY secret."];
  if (status === 404) return [503, "bad_model", "The AI model wasn't found. The site owner should check the AI_MODEL setting."];
  if (status === 429) return [429, "quota", "The free AI quota is used up for the moment. Please wait a minute and try again."];
  if (status >= 500) return [502, "busy", `The AI service is busy or having trouble (error ${status}). Please try again in a moment.`];
  return [502, "error", `Something went wrong (error ${status}). Please try again.`];
}

/* ---------- the chat endpoint ---------- */
async function chat(request, env) {
  if (!clean(env.AI_API_KEY)) return json(503, "This chatbot isn't connected to an AI service yet. The site owner needs to add the AI_API_KEY secret in Cloudflare.", "not_configured");
  const ip = request.headers.get("cf-connecting-ip") || "local";
  const wait = rateLimit(ip, Number(env.RATE_LIMIT_PER_MINUTE) || 15);
  if (wait) return json(429, `You're sending messages too quickly. Please wait ${wait} seconds and try again.`, "rate_limited", { "Retry-After": String(wait) });

  const raw = await request.text();
  if (raw.length > 120000) return json(413, "That conversation is too long. Start a new chat and try again.", "too_large");
  let body;
  try { body = JSON.parse(raw); } catch (e) { return json(400, "The request couldn't be read.", "bad_request"); }
  const turns = validate(body);
  if (!turns) return json(400, "The message was empty, too long, or in an unexpected format.", "bad_request");

  const refs = references(turns.filter((t) => t.role === "user").slice(-2).map((t) => t.content).join(" "));
  const model = clean(env.AI_MODEL) || DEFAULT_MODEL;
  let res;
  try {
    res = await callGemini(env, model, turns, refs, request.signal);
    if (res.status >= 500) { await sleep(800); res = await callGemini(env, model, turns, refs, request.signal); }
    if (!res.ok && model !== FALLBACK_MODEL && (res.status === 400 || res.status === 404 || res.status >= 500)) {
      const t = await res.clone().text();
      if (!/api key|API_KEY_INVALID/i.test(t)) res = await callGemini(env, FALLBACK_MODEL, turns, refs, request.signal);
    }
  } catch (e) {
    return json(502, "Nova AI couldn't reach the AI service. Please try again.", "unreachable");
  }
  if (!res.ok || !res.body) {
    const [status, code, message] = explain(res.status, await res.text());
    console.log("AI service status:", res.status); // only the status code is logged, never keys or messages
    return json(status, message, code);
  }
  return new Response(toText(res.body), {
    headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store, no-transform", "X-Content-Type-Options": "nosniff" },
  });
}

/* ---------- setup check: open /api/health?test=1 ---------- */
async function health(env, url) {
  const key = clean(env.AI_API_KEY);
  const base = { keyFound: !!key, model: clean(env.AI_MODEL) || DEFAULT_MODEL };
  const out = (o, s = 200) => new Response(JSON.stringify(o, null, 2), { status: s, headers: { "Content-Type": "application/json", "Cache-Control": "no-store" } });
  if (!key) return out({ ...base, help: "AI_API_KEY is missing. In Cloudflare: your Worker > Settings > Variables and Secrets > add AI_API_KEY as a Secret, then Deploy." });
  if (url.searchParams.get("test") !== "1") return out({ ...base, help: "Key found. Add ?test=1 to the address to run a real connection test." });
  try {
    const r = await fetch(`${GEMINI}${encodeURIComponent(base.model)}:generateContent`, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-goog-api-key": key },
      signal: AbortSignal.timeout(20000),
      body: JSON.stringify({ contents: [{ role: "user", parts: [{ text: "Reply with the word OK." }] }] }),
    });
    if (r.ok) return out({ ...base, connected: true, help: "Connected. The key and model work." });
    const [, , message] = explain(r.status, await r.text());
    return out({ ...base, connected: false, upstreamStatus: r.status, help: message });
  } catch (e) {
    return out({ ...base, connected: false, help: "Couldn't reach Google from the server." });
  }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/api/chat" && request.method === "POST") return chat(request, env);
    if (url.pathname === "/api/health") return health(env, url);
    if (url.pathname === "/" || url.pathname === "/index.html") {
      return new Response(PAGE, {
        headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-cache", "X-Content-Type-Options": "nosniff", "Referrer-Policy": "no-referrer" },
      });
    }
    return new Response("Not found", { status: 404 });
  },
};
